measures.expression:
COUNTROWS(
    FILTER(
        VALUES(Dim_Application[ApplicationKey]),
        NOT ISBLANK([Availability %]) && [Availability %] >= [Committed Uptime Target %]
    )
)

COUNTROWS(
    FILTER(
        VALUES(Dim_Application[ApplicationKey]),
        [Uptime RAG Status] = "Red"
    )
)
